const controlsBeforeWalking=renderControls;renderControls=function(){controlsBeforeWalking();const o=object();if(!isAnimatedCharacter(o))return;const details=document.createElement('details');details.innerHTML='<summary>Walking style</summary><label>Step length<input id="walkStride" type="range" min="0.5" max="1.3" step="0.05"></label><label>Foot lift<input id="walkLift" type="range" min="0.08" max="0.3" step="0.01"></label><label>Arm swing<input id="walkArmSwing" type="range" min="0" max="1.5" step="0.05"></label><p class="note">Walking drives the hip and knee joints automatically. Step phase follows travel distance. Training is not required.</p>'+(o.type==='puppet'?'<p class="note">'+(canAnimateWalk(o)?'Both leg chains are ready.':'Missing leg setup: '+walkLegHint(o))+'.</p><button id="setupWalkingLegs">Set up leg joints</button>':'');$('controls').append(details);for(const[id,key,defaultValue]of[['walkStride','walkStride',1],['walkLift','walkLift',.16],['walkArmSwing','walkArmSwing',1]]){$(id).value=o[key]??defaultValue;$(id).disabled=!!o.locked;$(id).oninput=e=>{if(o.locked)return;o[key]=+e.target.value;save();draw()}}if($('setupWalkingLegs')){$('setupWalkingLegs').disabled=!!o.locked;$('setupWalkingLegs').onclick=()=>openImageRig(o)}};
